 12	import { drive } from '../explore/drive';
 13	import { bike } from '../explore/bike';
 14	import { CONFIG } from '../config';
 15	import { inEase, inPose, inOrbit, type InVec, type InShot } from './shots';
 16	import type { InSceneId } from './timeline';
 17	import type { GliderInput } from '../explore/flight';
 18	import type { DrInput } from '../explore/drive/motion';
 19	import type { BkInput } from '../explore/bike/motion';
 20	import type { StInput } from '../explore/stroll/motion';
 21	import type { SwingController } from '../bridges/song-han/SwingController';
 22	
 23	export interface InSceneRun { enter(): void; update(t: number, dt: number): void; leave(): void }
 24	
 25	const I = CONFIG.intro, D = I.demo;
 26	const durOf = (id: InSceneId): number => { for (const s of I.scenes) if (s.id === id) return s.dur; return 1; };
 27	const _p: InVec = [0, 0, 0], _t: InVec = [0, 0, 0];   // tư thế camera dùng lại mỗi khung
 28	let ctrl: SwingController | null = null;
 29	let st = 0;                                            // giây trong nhịp hiện tại (hàm auto đọc; update ghi trước khi chế độ chạy)
 30	
 31	/* Cờ tiễn Cầu sông Hàn: index.ts chạy mỗi khung (cả sau cleanup) tới khi cầu CLOSED */
 32	export const inSee = { off: false };
 33	
 34	export function inScenesInit(c: SwingController): void { ctrl = c; }
 35	
 36	/* Camera nhịp toàn cảnh: nội suy shot theo t / dur; cam.mode 'intro' (stop() của chế độ trước đưa về 'orbit') */
 37	function wide(shot: InShot, t: number, dur: number): void {
 38	  inPose(shot, t / dur, _p, _t);
 39	  place();
 40	}
 41	function place(): void {
 42	  camera.position.set(_p[0], _p[1], _p[2]);
 43	  controls.target.set(_t[0], _t[1], _t[2]);
 44	  camera.lookAt(controls.target);
 45	}
 46	function introCam(): void { cam.flight.then = null; cam.mode = 'intro'; controls.enabled = false; }
 47	
 48	/* ---------- tự lái (một hàm cho mỗi chế độ, tạo một lần) ---------- */
 49	const gAuto = (inp: GliderInput): void => {
 50	  inp.turn = (st >= D.glider.turnFrom && st <= D.glider.turnTo ? D.glider.turn : 0) as -1 | 0 | 1;
 51	  inp.climb = D.glider.climb as -1 | 0 | 1; inp.throttle = 0;
 52	};
 53	const cAuto = (inp: DrInput): void => { inp.gas = D.car.gas; inp.brake = 0; inp.steer = 0; inp.hand = false; };
 54	const bAuto = (inp: BkInput): void => { inp.gas = D.bike.gas; inp.brake = 0; inp.steer = 0; inp.hard = false; };
 55	let walkYaw = 0;                                       // hướng xuất phát của người đi dạo (đi thẳng theo hướng này, không theo camera)
 56	const wAuto = (inp: StInput): void => { inp.mz = 1; inp.mx = 0; inp.run = D.walk.run; inp.camYaw = walkYaw; };
 57	
 58	let fired = false, watered = false, viewed = false, finAng = 0;
 59	
 60	export const inScenes: Record<InSceneId, InSceneRun> = {
 61	  welcome: {
 62	    enter() { introCam(); },
 63	    update(t) { wide(I.shots.welcome, t, durOf('welcome')); },
 64	    leave() { /* chỉ camera */ }
 65	  },
 66	  glider: {
 67	    enter() { st = 0; explore.start({ pos: D.glider.pos as InVec, yaw: D.glider.yaw }); explore.auto = gAuto; },
 68	    update(t) { st = t; },
 69	    leave() { explore.auto = null; explore.stop(); }
 70	  },
 71	  car: {
 72	    enter() { st = 0; drive.start(); drive.auto = cAuto; },
 73	    update(t) {
 74	      st = t;
 75	      const c = drive.cam, e = inEase(t / D.car.camYawS);   // như kéo chuột (drCamDrag): lệch yaw / pitch + idle = 0 để camera không tự trả về giữa chừng
 76	      c.yaw = D.car.camYawFrom + (D.car.camYawTo - D.car.camYawFrom) * e; c.pitch = D.car.camPitchFrom * (1 - e); c.idle = 0;
 77	    },
 78	    leave() { drive.auto = null; drive.stop(); }
 79	  },
 80	  bike: {
 81	    enter() { st = 0; viewed = false; bike.start(); bike.auto = bAuto; },
 82	    update(t) { st = t; if (!viewed && t >= D.bike.viewAt) { viewed = true; bike.setView(3); } },
 83	    leave() { bike.auto = null; bike.stop(); }
 84	  },
 85	  walk: {
 86	    enter() { st = 0; stroll.start(); walkYaw = stroll.state ? stroll.state.yaw : 0; stroll.auto = wAuto; stroll.cam.yaw = walkYaw + D.walk.camYawFrom; },
 87	    update(t) { st = t; stroll.cam.yaw = walkYaw + D.walk.camYawFrom * (1 - inEase(t / D.walk.camYawS)); },
 88	    leave() { stroll.auto = null; stroll.stop(); }
 89	  },
 90	  daynight: {
 91	    enter() { introCam(); },
 92	    update(t) {
 93	      const r = I.nightRamp, k = (t - r[0]) / (r[1] - r[0]);
 94	      dayNight.target = k < 0 ? 0 : k > 1 ? 1 : k;
 95	      wide(I.shots.daynight, t, durOf('daynight'));
 96	    },
 97	    leave() { /* đêm giữ nguyên cho nhịp sau */ }
 98	  },
 99	  dragon: {
100	    enter() { introCam(); fired = false; watered = false; if (show.on) { show.on = false; show.t = 0; } },
101	    update(t) {
102	      if (!fired && t >= I.dragon.fireAt) { fired = true; show.on = true; show.t = 0; }      // lửa: chu kỳ thật bắt đầu từ lượt phun đầu
103	      if (!watered && t >= I.dragon.waterAt) { watered = true; show.on = true; show.t = 27; }   // rút gọn: nhảy sang đoạn phun nước (27–42 s của chu kỳ 48 s)
104	      wide(I.shots.dragon, t, durOf('dragon'));
105	    },
106	    leave() { show.on = false; show.t = 0; }
107	  },
108	  swing: {
109	    enter() {
110	      introCam();
111	      const c = ctrl; if (!c) return;
112	      if (c.state === 'CLOSED') { if (c.canStart()) c.start(I.swingSpeed); }   // bão: canStart sai thì thôi, nhịp vẫn chạy camera
113	      else { inSee.off = false; c.speed = I.swingSpeed; }                       // cầu chưa về CLOSED (vào lại nhịp): để cầu đi tiếp, OPEN thì giữ mở tới leave
114	    },
115	    update(t) { wide(I.shots.swing, t, durOf('swing')); },
116	    leave() { if (ctrl && ctrl.state !== 'CLOSED') inSee.off = true; }
117	  },
118	  finale: {
119	    enter() { introCam(); finAng = 0; },
120	    update(t, dt) {
121	      const dur = durOf('finale');
122	      inPose(I.shots.finale, t / dur, _p, _t);
123	      if (t >= dur) { finAng += I.drift * dt; inOrbit(_p, _t, finAng); }   // hết thời lượng: trôi chậm quanh điểm nhìn, chờ người xem bấm
124	      place();
125	    },
126	    leave() { /* chỉ camera */ }
127	  }
128	};
  1	/* ===== Đoạn giới thiệu điện ảnh: đồng hồ nhịp (thuần, không import three / DOM) — D-045 ===== */
  2	export type InSceneId = 'welcome' | 'glider' | 'car' | 'bike' | 'walk' | 'daynight' | 'dragon' | 'swing' | 'finale';
  3	export interface InScene { id: InSceneId; chapter: number; dur: number }
  4	export interface InClock { i: number; t: number; paused: boolean; done: boolean }   // i: nhịp đang chạy; t: giây trong nhịp; done: nhịp cuối đã hết thời lượng
  5	
  6	export function inCreate(): InClock { return { i: 0, t: 0, paused: false, done: false }; }
  7	
  8	/* Trả chỉ số nhịp mới nếu vừa sang nhịp, không thì −1. Tạm dừng thì không đổi gì; nhịp cuối kẹp t ở dur, done = true */
  9	export function inAdvance(c: InClock, scenes: readonly InScene[], dt: number): number {
 10	  if (c.paused) return -1;
 11	  const last = scenes.length - 1;
 12	  if (c.i >= last) { c.t = Math.min(c.t + dt, scenes[last].dur); if (c.t >= scenes[last].dur) c.done = true; return -1; }
 13	  c.t += dt;
 14	  if (c.t < scenes[c.i].dur) return -1;
 15	  c.t -= scenes[c.i].dur; c.i++;
 16	  if (c.i >= last && c.t >= scenes[last].dur) { c.t = scenes[last].dur; c.done = true; }
 17	  return c.i;
 18	}
 19	
 20	export function inSeek(c: InClock, scenes: readonly InScene[], i: number): number {
 21	  c.i = Math.max(0, Math.min(scenes.length - 1, i | 0)); c.t = 0; c.done = false; return c.i;
 22	}
 23	
 24	/* Độ đục màn tối 0–1: đầu nhịp 1 → 0 trong fade (first: không), cuối nhịp 0 → 1 trong fade (last: không) */
 25	export function inFade(t: number, dur: number, fade: number, first: boolean, last: boolean): number {
 26	  let a = 0;
 27	  if (!first && t < fade) a = Math.max(a, 1 - t / fade);
 28	  if (!last && t > dur - fade) a = Math.max(a, 1 - (dur - t) / fade);
 29	  return Math.max(0, Math.min(1, a));
 30	}
 31	
 32	/* Mức đầy 0–1 của đoạn tiến trình thứ k: trước i là 1, sau i là 0, tại i là t / dur */
 33	export function inFill(c: InClock, scenes: readonly InScene[], k: number): number {
 34	  if (k < c.i) return 1;
 35	  if (k > c.i) return 0;
 36	  return Math.max(0, Math.min(1, c.t / scenes[k].dur));
 37	}
 38	
 39	export function inShould(a: { explore: boolean; test: boolean; introParam: string | null; stored: string | null; seen: boolean; forced: boolean; reducedMotion: boolean; saveData: boolean }): boolean {
 40	  if (a.explore) return false;
 41	  if (a.introParam === 'off') return false;
 42	  if (a.test) return a.introParam !== null;
 43	  if (a.forced) return true;
 44	  return a.stored !== 'off' && !a.seen && !a.reducedMotion && !a.saveData;
 45	}

