     1	/* ===== Đoạn giới thiệu điện ảnh: lớp DOM #intro (D-045) =====
     2	   Chữ theo nhịp (số chương, tiêu đề, dòng phụ, ghi chú, hàng phím / dòng cảm ứng, nút hành động), thanh tiến trình 9 đoạn, ◀ ❚❚ ▶, "Không hiện lại", ô ngôn ngữ, khối lối vào ở nhịp cuối.
     3	   Khung DOM + CSS có sẵn trong index.html / main.css (mục "Đoạn giới thiệu (D-045)"); ở đây chỉ ghi chữ và móc nút. Mỗi khung chỉ ghi --f của đoạn đang chạy và độ đục màn tối, chỉ khi đổi đủ lớn. */
     4	import { t, onChange, getLang } from '../i18n';
     5	import { CONFIG } from '../config';
     6	import type { InSceneId } from './timeline';
     7	
     8	export type InActKind = 'glider' | 'car' | 'bike' | 'walk' | 'dragon' | 'swing' | 'tour';
     9	export interface InUiHandlers {
    10	  seek(i: number): void; prev(): void; next(): void; pause(): void; skip(): void;
    11	  act(kind: InActKind): void; replay(): void; noMore(on: boolean): void;
    12	}
    13	
    14	const S = CONFIG.intro.scenes;
    15	const ACT: Partial<Record<InSceneId, InActKind>> = { glider: 'glider', car: 'car', bike: 'bike', walk: 'walk', dragon: 'dragon', swing: 'swing' };   // nhịp có nút hành động
    16	const KEYS: Partial<Record<InSceneId, string>> = { glider: 'inK_glider', car: 'inK_car', bike: 'inK_bike', walk: 'inK_walk' };                   // nhịp có hàng phím
    17	const TOUCH: Partial<Record<InSceneId, string>> = { car: 'inTouch_car', bike: 'inTouch_bike', walk: 'inTouch_walk', glider: 'exDesktopOnly' };   // máy cảm ứng: một dòng thay hàng phím
    18	
    19	const $ = (id: string) => document.getElementById(id);
    20	let root: HTMLElement | null = null;
    21	const segs: HTMLButtonElement[] = [];
    22	const fills: number[] = [];      // --f đã ghi của từng đoạn
    23	let veilEl: HTMLElement | null = null, veilA = -1;   // độ đục màn tối đã ghi
    24	let curI = -1;
    25	const touchDev = (): boolean => typeof matchMedia === 'function' && matchMedia('(hover: none)').matches;
    26	
    27	/* Gắn DOM một lần: dựng 9 đoạn tiến trình, móc nút, ô ngôn ngữ (như wireLang của chooser.ts) */
    28	export function inUiSetup(h: InUiHandlers): void {
    29	  root = $('intro'); if (!root) return;
    30	  veilEl = $('inVeil');
    31	  const prog = $('inProg');
    32	  if (prog && !segs.length) {
    33	    let ch = -1;
    34	    S.forEach((s, i) => {
    35	      const b = document.createElement('button');
    36	      b.type = 'button'; b.className = 'in-seg' + (s.chapter !== ch ? ' in-ch' : ''); ch = s.chapter;
    37	      b.appendChild(document.createElement('i'));
    38	      b.addEventListener('click', () => h.seek(i));
    39	      prog.appendChild(b); segs.push(b); fills.push(-1);
    40	    });
    41	  }
    42	  const on = (id: string, f: () => void) => $(id)?.addEventListener('click', f);
    43	  on('inSkip', () => h.skip()); on('inPrev', () => h.prev()); on('inNext', () => h.next()); on('inPause', () => h.pause());
    44	  on('inStart', () => h.skip()); on('inReplay', () => h.replay()); on('inTour', () => h.act('tour'));
    45	  on('inAct', () => { const k = $('inAct')?.dataset.kind as InActKind | undefined; if (k) h.act(k); });
    46	  root.querySelectorAll<HTMLButtonElement>('button[data-in-pick]').forEach((b) => b.addEventListener('click', () => h.act(b.dataset.inPick as InActKind)));
    47	  const nm = $('inNoMore') as HTMLInputElement | null;
    48	  nm?.addEventListener('change', () => h.noMore(nm.checked));
    49	  const mine = $('inLang') as HTMLSelectElement | null, main = $('langSelect') as HTMLSelectElement | null;
    50	  if (mine && main) {
    51	    mine.innerHTML = main.innerHTML; mine.value = getLang();
    52	    mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
    53	  }
    54	  onChange((code) => { if (mine) mine.value = code; if (curI >= 0) inUiRender(curI); });
    55	}
    56	
    57	/* Hiện / ẩn lớp phủ; lúc hiện: ô dù lượn khóa trên cảm ứng, đặt lại bộ nhớ ghi */
    58	export function inUiShow(on: boolean): void {
    59	  if (!root) return;
    60	  root.hidden = !on;
    61	  if (!on) { curI = -1; delete root.dataset.scene; return; }
    62	  const g = root.querySelector<HTMLButtonElement>('button[data-in-pick="glider"]'); if (g) g.disabled = touchDev();
    63	  const mine = $('inLang') as HTMLSelectElement | null; if (mine) mine.value = getLang();
    64	  veilA = -1; for (let k = 0; k < fills.length; k++) fills[k] = -1;
    65	}
    66	
    67	export function inUiNoMore(on: boolean): void { const nm = $('inNoMore') as HTMLInputElement | null; if (nm) nm.checked = on; }
    68	
    69	/* Ghi chữ của nhịp i (đổi nhịp, đổi ngôn ngữ) */
    70	export function inUiRender(i: number): void {
    71	  if (!root) return;
    72	  const s = S[i], id = s.id, touch = touchDev();
    73	  curI = i;
    74	  root.dataset.scene = id;
    75	  const set = (eid: string, v: string) => { const e = $(eid); if (e && e.textContent !== v) e.textContent = v; };
    76	  set('inEyebrow', '0' + s.chapter + ' — ' + t('inCh' + s.chapter));
    77	  set('inTitle', t('inT_' + id)); set('inSub', t('inS_' + id));
    78	  const note = id === 'daynight' ? t('inWx') : id === 'dragon' ? t('inDragonNote') : id === 'swing' ? t('inFast', { n: CONFIG.intro.swingSpeed }) + ' · ' + t('inSwingNote') : '';
    79	  const ne = $('inNote'); if (ne) { ne.textContent = note; ne.hidden = !note; }
    80	  /* hàng phím: "phím|nghĩa;phím|nghĩa", phím cách nhau dấu cách → mỗi phím một <kbd>; cảm ứng: một dòng .in-touch */
    81	  const ke = $('inKeys');
    82	  if (ke) {
    83	    ke.textContent = '';
    84	    const tk = touch ? TOUCH[id] : undefined, kk = KEYS[id];
    85	    if (tk) { const sp = document.createElement('span'); sp.className = 'in-touch'; sp.textContent = t(tk); ke.appendChild(sp); }
    86	    else if (kk && !touch) {
    87	      for (const item of t(kk).split(';')) {
    88	        const [keys, mean] = item.split('|'); if (!mean) continue;
    89	        const sp = document.createElement('span'); sp.className = 'in-k';
    90	        for (const k of keys.trim().split(/\s+/)) { const kb = document.createElement('kbd'); kb.textContent = k; sp.appendChild(kb); }
    91	        const m = document.createElement('i'); m.textContent = mean; sp.appendChild(m);
    92	        ke.appendChild(sp);
    93	      }
    94	    }
    95	    ke.hidden = !ke.firstChild;
    96	  }
    97	  const act = $('inAct') as HTMLButtonElement | null, kind = ACT[id];
    98	  if (act) {
    99	    const show = !!kind && !(touch && kind === 'glider');   // dù lượn trên cảm ứng: không nút (dòng "Chỉ dùng trên máy tính")
   100	    act.hidden = !show;
   101	    if (show) { act.dataset.kind = kind; act.textContent = t('inTry_' + id); } else delete act.dataset.kind;
   102	  }
   103	  const end = $('inEnd'); if (end) end.hidden = id !== 'finale';
   104	  for (let k = 0; k < segs.length; k++) {
   105	    const f = k < i ? 1 : k > i ? 0 : fills[k] < 0 ? 0 : fills[k];
   106	    if (fills[k] !== f) { segs[k].style.setProperty('--f', String(f)); fills[k] = f; }
   107	    if (k === i) segs[k].setAttribute('aria-current', 'true'); else segs[k].removeAttribute('aria-current');
   108	    segs[k].setAttribute('aria-label', '0' + S[k].chapter + ' — ' + t('inT_' + S[k].id));
   109	  }
   110	  /* gắn lại .in-in để chạy lại hiệu ứng vào của khối chữ */
   111	  const cap = $('inCap');
   112	  if (cap) { cap.classList.remove('in-in'); void cap.offsetWidth; cap.classList.add('in-in'); }
   113	}
   114	
   115	/* Mỗi khung: mức đầy của đoạn đang chạy (chỉ ghi khi đổi ≥ 0,005) */
   116	export function inUiFill(i: number, f: number): void {
   117	  if (i < 0 || i >= segs.length) return;
   118	  if (Math.abs(f - fills[i]) < 0.005 && !(f === 1 && fills[i] !== 1)) return;
   119	  fills[i] = f; segs[i].style.setProperty('--f', f.toFixed(3));
   120	}
   121	
   122	/* Mỗi khung: độ đục màn tối (chỉ ghi khi đổi quá 0,01, hoặc chạm đúng 0 / 1) */
   123	export function inUiVeil(a: number): void {
   124	  if (!veilEl) return;
   125	  if (Math.abs(a - veilA) <= 0.01 && !((a === 0 || a === 1) && a !== veilA)) return;
   126	  veilA = a; veilEl.style.opacity = a.toFixed(3);
   127	}
   128	
   129	/* Nút ❚❚ / ▶: chữ, aria-pressed, khóa aria (i18n.apply đọc data-i18n-aria nên đổi khóa chứ không chỉ đổi nhãn) */
   130	export function inUiPaused(on: boolean): void {
   131	  const b = $('inPause'); if (!b) return;
   132	  b.textContent = on ? '▶' : '❚❚';
   133	  b.setAttribute('aria-pressed', String(on));
   134	  b.dataset.i18nAria = on ? 'inPlay' : 'inPause';
   135	  b.setAttribute('aria-label', t(on ? 'inPlay' : 'inPause'));
   136	}
