  const emit = (why: 'user' | 'feature' | 'data') => { for (const f of subs) { try { f(why); } catch (e) { console.error(e); } } };

  const calcSun = (force: boolean) => {
    const t = d.now();
    if (!force && Math.abs(t - sunAt) <= 1000) return;
    sunAt = t;
    const p = sunPosition(t, d.lat, d.lon);
    sunObj.elev = p.elev; sunObj.azim = p.azim; sunObj.warm = sunWarm(p.elev, cfg.warm);
    sun = sunObj;
  };
  /* Số liệu → đích thời tiết. Chỉ ở Trực tiếp; data null (đang tải / mất mạng không đệm) ⇒ không gọi gì, giữ trạng thái cuối */
  const applyData = (instant: boolean) => {
    const data = d.store.data;
    if (mode !== 'live' || !data) return;
    const up = sunObj.elev > 0;
    if (data === lastData && up === lastUp) return;
    lastData = data; lastUp = up;
    d.weather.setLive(envToParams(data, up, cfg), instant);
    applied = true;
    emit('data');
  };

  d.store.onChange(() => { if (mode === 'live') applyData(!applied && clock() - born <= cfg.instantMs); });
  if (mode === 'live') { calcSun(true); applyData(true); }       // kho có thể đã có số liệu (bộ nhớ đệm) trước khi bộ điều khiển được tạo

  return {
    get mode() { return mode; },
    get sun() { return mode === 'live' ? sun : null; },
    setMode(m: EnvMode, why: 'user' | 'feature' = 'user') {
      if (m === mode) return;
      if (m === 'manual') {
        mode = 'manual'; firstNight = false;
        d.weather.setLive(null);
        d.dayNight.target = manualTarget;
        sun = null;
      } else {
        manualTarget = d.dayNight.target;
        mode = 'live'; firstNight = false; applied = true;   // từ Mô phỏng: cảnh tiến dần tới trạng thái thật (không tức thì)
        d.weather.stopScenario(); d.weather.standTrees();
        const data = d.store.data;
        if (!data || d.now() - data.obs > d.refreshMs) void d.store.refresh();
        calcSun(true);
        d.dayNight.target = liveNight(sunObj.elev, cfg);
        lastData = null; lastUp = null;
        applyData(false);
      }
      emit(why);
    },
    update(_dt: number) {
      // Không dùng dt: đêm tiến dần bằng stepNight, thời tiết bằng stepWeather (cả hai nhận dt đã kẹp trong animate); sau tab ẩn lâu đích đổi một lần rồi cảnh tiến dần
      if (mode !== 'live') return;
      calcSun(false);
      d.dayNight.target = liveNight(sunObj.elev, cfg);
      if (firstNight) { d.dayNight.night = d.dayNight.target; firstNight = false; }
      if (lastData && (sunObj.elev > 0) !== lastUp) applyData(false);   // qua chân trời: mù nóng chỉ ban ngày (envToParams sunUp)
    },
    onChange(fn) { subs.push(fn); }
  };
}
  /* Cho test: số đo người treo của dù mình (pilot/index.ts plDebug); null khi chưa bay */
  pilotDebug() { return glider ? plDebug(glider) : null; },
  /* Tự lái (intro, D-045): khác null thì update() gọi auto(_inp) thay cho phím; bên gán ghi vào _inp, không cấp phát */
  auto: null as ((inp: GliderInput) => void) | null,
  /* at: điểm + hướng cất cánh (intro); bỏ trống thì cất cánh ở CONFIG.explore.takeoff như cũ */
  start(at?: { pos: [number, number, number]; yaw: number }): void {
    plPreload();
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    exMulti.onChange = onMultiChange;
    state = exCreate();
    const slot = exMulti.session ? exMulti.session.mySlot : -1;
    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
    if (at) { state.pos.set(at.pos[0], at.pos[1], at.pos[2]); state.yaw = at.yaw; }
    if (!saved) saved = { explore: document.body.classList.contains('explore'), show: show.on };
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    glider.visible = true;
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    plReset(glider);   // cất cánh mới: người treo không mang lò xo của lần bay trước
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    exShowSpeed();
    document.body.classList.add('explore');
  },
  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
  startWatching(carry = false): void {
    const s = exMulti.session; if (!s) return;
    plPreload();   // dù người khác dùng người treo có xương
    watching = true; chased = carry;
    keys.clear();
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    exWatchShow(s);
  },
  update(dt: number): void {
    if (watching) { watchStep(dt); return; }
    if (!active()) return;
    if (explore.auto) { explore.auto(_inp); advance(dt, _inp); return; }
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Rời bay mà không tải lại trang (intro, D-045): cất dù, trả lớp body / show.on / camera như trước start(). Đang xem hoặc chưa bay thì không làm gì; gọi nhiều lần an toàn */
  stop(): void {
    if (state === null || watching) return;
    state = null; keys.clear();
    if (glider) { glider.visible = false; glider.removeFromParent(); }
    if (saved) {
      if (!saved.explore) document.body.classList.remove('explore');
      if (show.on !== saved.show) { show.on = saved.show; show.t = 0; }
      saved = null;
    }
    if (cam.mode === 'glider') { cam.mode = 'orbit'; controls.enabled = true; }
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
};

/* deferChooser: gắn màn chọn như cũ nhưng chưa hiện (intro hiện bằng exRevealChooser khi xong) */
export function setupExplore(ctrl: SwingController, deferChooser = false): void {
  exNightBind(ctrl);
  setupStroll(ctrl, () => explore.exit());
  setupDrive(ctrl, () => explore.exit());
  setupBike(ctrl, () => explore.exit());
  window.addEventListener('keydown', (e) => {
    if (!inGlider() && !stroll.inMode() && !drive.inMode() && !bike.inMode()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe, xe máy và hai chế độ xem)
    if (watching || stroll.inMode() || drive.inMode() || bike.inMode()) return;   // xem: không lái; đi dạo / lái xe / xe máy: phím do stroll/index.ts, drive/index.ts, bike/index.ts ghi
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
  for (const id of ['langSelect', 'qualitySel']) {
    const sel = document.getElementById(id); if (!sel) continue;
    let byMouse = false;
    sel.addEventListener('pointerdown', () => { byMouse = true; });
    sel.addEventListener('keydown', () => { byMouse = false; });
    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active() || drive.active() || bike.active())) sel.blur(); byMouse = false; });
  }
  const q = new URLSearchParams(location.search);
  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
  if (q.get('explore') === 'bike') { bike.start(); return; }     // xe máy một mình
  if (!q.has('test') || q.has('chooser') || deferChooser) {   // deferChooser: ?test&intro cũng cần màn chọn (hiện khi intro xong / bỏ qua)
    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload());   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="glider"]')?.addEventListener('click', () => plPreload());   // chọn thẻ Dù lượn: nạp người treo ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
    document.querySelector('button[data-pick="bike"]')?.addEventListener('click', () => bike.preload());   // chọn thẻ Xe máy: nạp mô hình xe máy ngay (Task 3)
    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); else if (choice === 'bike') bike.start(); },
      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else if (choice === 'bike') bike.startWatching(); else explore.startWatching(); }, { defer: deferChooser });   // 'guided': màn chọn tự ẩn, giao diện cũ
  }
}

  constructor(cfg: SongHanConfig) {
    super();
    this.cfg = cfg;
  }
  get busy() { return this.state !== 'CLOSED'; }
  get allowEntry() { return this.state === 'CLOSED' || (this.state === 'REOPEN_TRAFFIC' && this.signal === 'green'); }
  start(speed?: number) {
    if (this.state !== 'CLOSED') return false;
    if (!this.canStart()) { this.dispatchEvent(new Event('swingBlocked')); return false; }
    if (speed) this.speed = speed;
    this.go('STOP_TRAFFIC'); this.dispatchEvent(new Event('swingStart'));
    return true;
  }
  requestClose() { if (this.state === 'OPEN') this.closeAsked = true; }
